<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderMetadataAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderMetadataAccessor trait.
 *
 * Covers null default, string/VO assignment via withMetadata,
 * getMetadata/metadata accessors, and isMetadataChanged with/without original.
 */
class TenantLoginProviderMetadataAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMetadata creates a new instance with the Metadata set
     * from a string value, and getMetadata returns the primitive string.
     */
    public function testWithMetadataFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderMetadataAccessorUnitTest();

        // Act
        $result = $holder->withMetadata('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->getMetadata());
    }
    /**
     * Asserts that withmetadata has access to the value object
     * from a string value, and getMetadata returns the primitive string.
     */
    public function testWithMetadataFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderMetadataAccessorUnitTest();

        // Act
        $result = $holder->withMetadata('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->metadata()->value());
    }
    public function testChangedMetadata(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderMetadataAccessorUnitTest();
        $original = $holder->withMetadata('store://bin');
        $same = $holder->withMetadata('store://bin');
        $modified = $holder->withMetadata('store://obin');

        // Act
        $unchanged = $holder->isMetadataChanged();
        $withSame = $original->isMetadataChanged($same);
        $withDiferent = $original->isMetadataChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderMetadataAccessorUnitTest
{
    use TenantLoginProviderMetadataAccessor;
}
